const studentNav = [
  { label: 'Overview', path: '/student/dashboard', icon: LayoutDashboard },
  { label: 'Give feedback', path: '/student/feedback', icon: MessageSquare },
  { label: 'My history', path: '/student/history', icon: ClipboardList },
  { label: 'My complaints', path: '/student/complaints', icon: CircleHelp },
  { label: 'My profile', path: '/student/profile', icon: Users },
];
const hostNav = [
  { label: 'Overview', path: '/host/dashboard', icon: LayoutDashboard },
  { label: 'Feedback', path: '/host/feedback', icon: MessageSquare },
  { label: 'Students', path: '/host/students', icon: Users },
  { label: 'Complaints', path: '/host/complaints', icon: CircleHelp },
  { label: 'Reports & analytics', path: '/host/reports', icon: BarChart3 },
  { label: 'Questions & periods', path: '/host/manage', icon: ClipboardList },
  { label: 'System settings', path: '/host/settings', icon: Settings },
];
const getToken = () => localStorage.getItem('campusvoice_token');
async function api(path, options = {}) {
  const response = await fetch(`/api${path}`, {
    ...options,
    headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(getToken() ? { Authorization: `Bearer ${getToken()}` } : {}), ...options.headers },
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.message || 'Something went wrong. Please try again.');
  return data;
}

function Brand({ small = false }) {
  return <Link to="/" className="flex items-center gap-2.5">
    <span className={`grid place-items-center rounded-xl bg-gradient-to-br from-violet-600 to-indigo-600 text-white shadow-lg shadow-violet-200 ${small ? 'h-9 w-9' : 'h-10 w-10'}`}><Activity size={21} strokeWidth={2.5} /></span>
    <span className="font-display text-[19px] font-extrabold tracking-tight text-[#25243b] dark:text-white">Campus<span className="text-violet-600">Voice</span></span>
  </Link>;
}
function ThemeButton() {
  const [dark, setDark] = useState(document.documentElement.classList.contains('dark'));
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('campusvoice_theme', dark ? 'dark' : 'light'); }, [dark]);
  return <button aria-label="Toggle dark mode" onClick={() => setDark(!dark)} className="grid h-10 w-10 place-items-center rounded-xl border border-slate-200 text-slate-600 transition hover:bg-slate-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800">{dark ? <Sun size={18} /> : <Moon size={18} />}</button>;
}
function Home() {
  const [counts, setCounts] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => { api('/public/stats').then(setCounts).catch(() => {}); }, []);
  return <div className="home-shell min-h-screen overflow-hidden bg-[#faf9ff]">
    <header className="relative z-10 mx-auto flex max-w-7xl items-center justify-between px-6 py-5 lg:px-10">
      <Brand />
      <nav className="hidden items-center gap-8 text-sm font-medium text-slate-600 md:flex">
        <a href="#about" className="transition hover:text-violet-700">About</a><a href="#categories" className="transition hover:text-violet-700">Feedback categories</a><a href="#access" className="transition hover:text-violet-700">Get started</a>
      </nav>
      <div className="flex items-center gap-2"><ThemeButton/><button aria-label="Toggle navigation" aria-expanded={menuOpen} onClick={()=>setMenuOpen(!menuOpen)} className="grid h-10 w-10 place-items-center rounded-xl border border-slate-200 text-slate-600 md:hidden">{menuOpen?<X size={18}/>:<Menu size={18}/>}</button><Link to="/login/student" className="hidden rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-semibold text-white shadow-md shadow-violet-200 transition hover:bg-violet-700 sm:inline-flex">Sign in <ArrowRight className="ml-2" size={16} /></Link><Link aria-label="Sign in" to="/login/student" className="rounded-xl bg-violet-600 p-2.5 text-white sm:hidden"><ArrowRight size={17} /></Link></div>
      {menuOpen&&<nav className="absolute left-6 right-6 top-full mt-2 grid gap-1 rounded-2xl border border-slate-100 bg-white p-2 shadow-xl md:hidden"><a onClick={()=>setMenuOpen(false)} href="#about" className="rounded-xl px-3 py-2.5 text-sm font-medium text-slate-700 hover:bg-violet-50">About</a><a onClick={()=>setMenuOpen(false)} href="#categories" className="rounded-xl px-3 py-2.5 text-sm font-medium text-slate-700 hover:bg-violet-50">Feedback categories</a><a onClick={()=>setMenuOpen(false)} href="#access" className="rounded-xl px-3 py-2.5 text-sm font-medium text-slate-700 hover:bg-violet-50">Get started</a></nav>}
    </header>
    <main>
      <section className="relative mx-auto grid max-w-7xl items-center gap-12 px-6 pb-20 pt-10 lg:grid-cols-[1.05fr_.95fr] lg:px-10 lg:pb-28 lg:pt-14">
        <div className="pointer-events-none absolute -left-48 top-8 h-[460px] w-[460px] rounded-full bg-violet-200/30 blur-3xl" />
        <motion.div initial={{ opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .6 }} className="relative">
          <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-violet-100 bg-white/80 px-3.5 py-2 text-xs font-semibold text-violet-700 shadow-sm"><Sparkles size={14} /> A better campus starts with being heard</div>
          <h1 className="font-display max-w-2xl text-5xl font-extrabold leading-[1.12] tracking-[-.055em] text-[#22213b] sm:text-6xl lg:text-[70px]">Your campus.<br /><span className="bg-gradient-to-r from-violet-600 to-indigo-500 bg-clip-text text-transparent">Your voice.</span><br />Real change.</h1>
          <p className="mt-6 max-w-xl text-lg leading-8 text-slate-600">A more thoughtful way to share feedback, raise concerns, and help shape a campus where everyone can thrive.</p>
          <div className="mt-8 flex flex-wrap items-center gap-4"><a href="#access" className="inline-flex items-center rounded-xl bg-violet-600 px-5 py-3.5 font-semibold text-white shadow-lg shadow-violet-200 transition hover:-translate-y-0.5 hover:bg-violet-700">Find your portal <ArrowRight className="ml-2" size={17} /></a><a href="#about" className="px-3 py-3 text-sm font-semibold text-slate-600 hover:text-violet-700">Discover CampusVoice <ArrowDown className="ml-1 inline" size={15} /></a></div>
          <div className="mt-10 flex items-center gap-4 border-t border-violet-100 pt-6"><div className="flex -space-x-2">{['A','S','R','M'].map((x,i)=><span key={x} className={`grid h-9 w-9 place-items-center rounded-full border-2 border-[#faf9ff] text-xs font-bold text-white ${['bg-violet-500','bg-indigo-500','bg-fuchsia-500','bg-blue-500'][i]}`}>{x}</span>)}</div><p className="text-sm text-slate-600"><b className="text-slate-900">{counts?.students ?? 'Your community'}</b> making every idea count</p></div>
        </motion.div>
        <motion.div initial={{ opacity: 0, scale: .96 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: .7, delay: .12 }} className="relative mx-auto w-full max-w-[550px]">
          <div className="absolute -right-4 -top-5 h-32 w-32 rounded-full bg-indigo-200/40 blur-3xl" />
          <div className="relative rounded-[30px] border border-white/80 bg-white/85 p-5 shadow-[0_35px_90px_-40px_rgba(84,58,150,.35)] backdrop-blur-xl sm:p-7">
            <div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-slate-500">The campus pulse</p><p className="mt-1 font-display text-2xl font-extrabold text-slate-900">Small voices. Big impact.</p></div><div className="grid h-12 w-12 place-items-center rounded-2xl bg-violet-50 text-violet-600"><Gauge size={24} /></div></div>
            <div className="mt-6 rounded-2xl bg-gradient-to-r from-violet-600 to-indigo-600 p-5 text-white"><div className="flex justify-between"><div><p className="text-sm text-violet-100">Feedback that moves us forward</p><p className="mt-2 text-3xl font-bold">{counts?.feedback ?? '—'} <span className="text-sm font-medium text-violet-100">responses shared</span></p></div><ArrowUpRight size={22} /></div><div className="mt-5 flex h-[88px] items-end gap-2">{[36,48,42,66,53,74,62,90,68,82,100,78,94,72,100].map((h,i)=><div key={i} style={{height:`${h}%`}} className={`flex-1 rounded-t-md ${i>10?'bg-white':'bg-white/35'}`} />)}</div></div>
            <div className="mt-5 grid grid-cols-2 gap-3">{categories.slice(0,4).map(({name,icon:Icon,color},i)=><div key={name} className="flex items-center gap-3 rounded-xl border border-slate-100 p-3"><span className={`grid h-9 w-9 place-items-center rounded-xl ${color}`}><Icon size={17}/></span><div><p className="text-xs font-semibold text-slate-800">{name}</p><p className="mt-0.5 text-[10px] text-slate-400">{['Be heard','Find your focus','Share an idea','Get moving'][i]}</p></div></div>)}</div>
            <div className="absolute -left-5 bottom-20 hidden items-center gap-3 rounded-2xl border border-white bg-white p-3.5 shadow-xl sm:flex"><span className="grid h-10 w-10 place-items-center rounded-full bg-emerald-50 text-emerald-600"><CheckCircle2 size={21}/></span><div><p className="text-xs font-bold text-slate-800">Your voice matters</p><p className="text-[11px] text-slate-500">Every idea counts</p></div></div>
          </div>
        </motion.div>
      </section>
      <section id="about" className="border-y border-violet-100/70 bg-white/65"><div className="mx-auto grid max-w-7xl gap-10 px-6 py-14 md:grid-cols-[.8fr_1.2fr] md:items-center lg:px-10"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-violet-600">One community, one conversation</p><h2 className="font-display mt-3 text-3xl font-extrabold tracking-tight text-slate-900 sm:text-4xl">Make campus better,<br/>together.</h2></div><p className="max-w-2xl text-base leading-7 text-slate-600">CampusVoice connects students and campus leaders in one shared place. Share honest feedback, follow up on concerns, and turn everyday experiences into practical improvements—with privacy and respect built in.</p></div></section>
      <section id="categories" className="mx-auto max-w-7xl px-6 py-16 lg:px-10 lg:py-20"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-violet-600">A voice for every corner</p><h2 className="font-display mt-3 text-3xl font-extrabold tracking-tight text-slate-900 sm:text-4xl">What would you like to improve?</h2></div><p className="max-w-sm text-sm leading-6 text-slate-500">From the classroom to the spaces between—your perspective helps make it better.</p></div><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{categories.map(({name,description,icon:Icon,color},i)=><motion.div key={name} initial={{opacity:0,y:12}} whileInView={{opacity:1,y:0}} viewport={{once:true}} transition={{delay:i*.05}} className="rounded-2xl border border-slate-100 bg-white p-5 transition hover:-translate-y-1 hover:shadow-lg hover:shadow-violet-100/70"><span className={`grid h-11 w-11 place-items-center rounded-2xl ${color}`}><Icon size={21}/></span><h3 className="mt-4 font-display text-base font-bold text-slate-900">{name}</h3><p className="mt-1 text-sm text-slate-500">{description}</p></motion.div>)}</div></section>
      <section id="access" className="mx-auto max-w-7xl px-6 pb-20 lg:px-10"><div className="rounded-[30px] bg-gradient-to-br from-[#211b43] via-[#30205f] to-[#4632a0] p-7 text-white sm:p-10 lg:p-12"><div className="mx-auto max-w-3xl text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-white/10"><Sparkles size={22}/></div><h2 className="font-display mt-5 text-3xl font-extrabold sm:text-4xl">Your campus. Your say.</h2><p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-violet-100">Choose your space to get started. One CampusVoice, designed for every perspective.</p></div><div className="mx-auto mt-8 grid max-w-4xl gap-4 md:grid-cols-2">
          <Link to="/login/student" className="group rounded-2xl border border-white/15 bg-white/[.08] p-6 text-left transition hover:-translate-y-1 hover:bg-white/[.13]"><div className="flex items-start justify-between"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-violet-300/15 text-violet-200"><GraduationCap size={24}/></span><ArrowUpRight className="text-white/60 transition group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-white" size={20}/></div><h3 className="mt-5 font-display text-xl font-bold">I’m a student</h3><p className="mt-2 text-sm leading-6 text-violet-100/80">Share feedback, raise a concern, and see the difference you make.</p><span className="mt-5 inline-flex items-center text-sm font-semibold text-white">Student sign in <ArrowRight className="ml-2" size={15}/></span></Link>
          <Link to="/login/host" className="group rounded-2xl border border-white/15 bg-white/[.08] p-6 text-left transition hover:-translate-y-1 hover:bg-white/[.13]"><div className="flex items-start justify-between"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-indigo-300/15 text-indigo-200"><Shield size={23}/></span><ArrowUpRight className="text-white/60 transition group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-white" size={20}/></div><h3 className="mt-5 font-display text-xl font-bold">I’m a campus host</h3><p className="mt-2 text-sm leading-6 text-violet-100/80">Understand what students need and turn insights into action.</p><span className="mt-5 inline-flex items-center text-sm font-semibold text-white">Authorized host sign in <ArrowRight className="ml-2" size={15}/></span></Link>
        </div></div></section>
    </main>
    <footer className="border-t border-slate-200/70 bg-white/50"><div className="mx-auto flex max-w-7xl flex-col gap-4 px-6 py-7 sm:flex-row sm:items-center sm:justify-between lg:px-10"><Brand small/><p className="text-xs text-slate-500">Built for a campus where every voice can make a difference.</p><p className="text-xs text-slate-400">© {new Date().getFullYear()} CampusVoice</p></div></footer>
  </div>;
}

function Login() {
  const { role } = useParams(); const isHost = role === 'host'; const navigate = useNavigate();
  const [mode,setMode]=useState('login'); const [form,setForm]=useState({email:'',password:'',name:'',studentId:''}); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  useEffect(()=>{setError('');setMode('login');},[role]);
  async function submit(event) {
    event.preventDefault();setBusy(true);setError('');
    try {
      const { token,user } = await api(`/auth/${mode}`, { method:'POST', body:JSON.stringify({ ...form, role:isHost?'host':'student' }) });
      localStorage.setItem('campusvoice_token',token);localStorage.setItem('campusvoice_user',JSON.stringify(user));
      navigate(user.role==='host'?'/host/dashboard':'/student/dashboard',{replace:true});
    } catch(e) { setError(e.message); } finally { setBusy(false); }
  }
  return <div className="login-shell grid min-h-screen bg-[#f7f6fc] lg:grid-cols-2">
    <div className="relative hidden overflow-hidden bg-gradient-to-br from-[#211b43] via-[#34256a] to-[#5141b6] p-12 text-white lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-32 top-20 h-96 w-96 rounded-full bg-violet-400/20 blur-3xl"/><div className="relative"><Brand/><Link to="/" className="mt-14 inline-flex items-center gap-2 text-sm text-violet-200 hover:text-white"><ArrowLeft size={16}/> Back to home</Link></div><div className="relative max-w-lg"><div className="mb-5 grid h-14 w-14 place-items-center rounded-2xl border border-white/15 bg-white/10">{isHost?<Shield size={26}/>:<GraduationCap size={27}/>}</div><h1 className="font-display text-5xl font-extrabold leading-tight">{isHost?'Lead with insight.':'Your voice can'}<br/><span className="text-violet-300">{isHost?'Build a better campus.':'change your campus.'}</span></h1><p className="mt-5 max-w-md text-base leading-7 text-violet-100/80">{isHost?'See the full picture, listen to what matters, and turn campus feedback into meaningful change.':'A better campus starts with a conversation. Tell us what is working—and what could work better.'}</p><div className="mt-9 flex items-center gap-3 text-sm text-violet-100/80"><CheckCircle2 size={17} className="text-emerald-300"/> One secure place for campus feedback</div></div><p className="relative text-xs text-violet-200/60">CampusVoice · Your campus, heard.</p></div>
    <div className="flex flex-col px-6 py-6 sm:px-10 lg:px-16"><div className="flex items-center justify-between lg:justify-end"><span className="lg:hidden"><Brand/></span><ThemeButton/><Link to="/" className="hidden text-sm text-slate-500 hover:text-violet-700 lg:inline-flex lg:ml-4">Back to home</Link></div>
      <div className="mx-auto my-auto w-full max-w-[430px] py-10"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-violet-100 text-violet-700 lg:hidden">{isHost?<Shield/>:<GraduationCap/>}</span><p className="mt-5 text-sm font-semibold text-violet-700">{isHost?'Campus host portal':'Student portal'}</p><h2 className="font-display mt-2 text-3xl font-extrabold tracking-tight text-slate-900">{mode==='register'?'Create your account':'Welcome back'}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{mode==='register'?'Join your campus community and make your voice count.':'Sign in to continue to your CampusVoice dashboard.'}</p>
        {error&&<div role="alert" className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
        <form onSubmit={submit} className="mt-7 space-y-4">{mode==='register'&&<><label className="block text-sm font-medium text-slate-700">Full name<input required autoComplete="name" className="field mt-2" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Your name"/></label><label className="block text-sm font-medium text-slate-700">Student ID<input required className="field mt-2" value={form.studentId} onChange={e=>setForm({...form,studentId:e.target.value})} placeholder="e.g. CV2026001"/></label></>}
          <label className="block text-sm font-medium text-slate-700">Email address<span className="relative mt-2 block"><Mail className="absolute left-3.5 top-3.5 text-slate-400" size={17}/><input required type="email" autoComplete="email" className="field pl-10" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder={isHost?'you@college.edu':'you@college.edu'}/></span></label>
          <label className="block text-sm font-medium text-slate-700">Password<input required type="password" autoComplete={mode==='register'?'new-password':'current-password'} minLength={8} className="field mt-2" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder="At least 8 characters"/></label>
          <button disabled={busy} className="flex w-full items-center justify-center rounded-xl bg-violet-600 py-3.5 text-sm font-bold text-white shadow-lg shadow-violet-200 transition hover:bg-violet-700 disabled:opacity-60">{busy?'Please wait…':mode==='register'?'Create student account':`Sign in as ${isHost?'host':'student'}`}<ArrowRight className="ml-2" size={16}/></button>
        </form>
        {!isHost&&<p className="mt-5 text-center text-sm text-slate-500">{mode==='register'?'Already have an account?':'New to CampusVoice?'} <button onClick={()=>{setMode(mode==='register'?'login':'register');setError('')}} className="font-semibold text-violet-700 hover:text-violet-800">{mode==='register'?'Sign in':'Create student account'}</button></p>}
        {isHost&&<p className="mt-5 flex items-center justify-center gap-2 text-xs text-slate-500"><Shield size={14}/> Host access is limited to authorized accounts.</p>}
        <div className="mt-8 border-t border-slate-200 pt-5 text-center"><Link to={isHost?'/login/student':'/login/host'} className="text-sm font-medium text-slate-500 hover:text-violet-700">Looking for the {isHost?'student':'host'} portal? <span className="font-semibold text-violet-700">Go here</span></Link></div>
      </div>
      <p className="text-center text-xs text-slate-400">Your information is protected and handled with care.</p>
    </div>
  </div>;
}

function Guard({ role }) {
  const user = useAuthUser();
  if (!user) return <Navigate to={`/login/${role}`} replace/>;
  if (user.role !== role) return <Navigate to={user.role==='host'?'/host/dashboard':'/student/dashboard'} replace/>;
  return <Outlet/>;
}
function useAuthUser() {
  const [user,setUser]=useState(()=>{try{return JSON.parse(localStorage.getItem('campusvoice_user')||'null')}catch{return null}});
  useEffect(()=>{const update=()=>{try{setUser(JSON.parse(localStorage.getItem('campusvoice_user')||'null'))}catch{setUser(null)}};window.addEventListener('storage',update);return()=>window.removeEventListener('storage',update)},[]);
  return user;
}
function AppLayout({ role }) {
  const user=useAuthUser();const location=useLocation();const navigate=useNavigate();const isHost=role==='host';const nav=isHost?hostNav:studentNav;const [open,setOpen]=useState(false);
  function logout(){localStorage.removeItem('campusvoice_token');localStorage.removeItem('campusvoice_user');navigate('/',{replace:true})}
  const title=nav.find(x=>x.path===location.pathname)?.label||'Overview';
  return <div className="dashboard-bg min-h-screen text-slate-900 dark:text-slate-100"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[260px] flex-col border-r border-slate-200/70 bg-white px-4 py-5 transition-transform dark:border-slate-800 dark:bg-[#191925] lg:translate-x-0 ${open?'translate-x-0':'-translate-x-full'}`}><div className="flex items-center justify-between px-2"><Brand/><button onClick={()=>setOpen(false)} className="rounded-lg p-2 text-slate-500 lg:hidden"><X size={18}/></button></div><div className="mt-9 px-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">{isHost?'Administration':'Your campus'}</div><nav className="mt-3 space-y-1">{nav.map(({label,path,icon:Icon})=><Link onClick={()=>setOpen(false)} key={path} to={path} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-semibold transition ${location.pathname===path?'nav-active':'text-slate-600 hover:bg-slate-50 dark:text-slate-300 dark:hover:bg-slate-800'}`}><Icon size={17}/>{label}</Link>)}</nav><div className="mt-auto rounded-2xl bg-gradient-to-br from-violet-50 to-indigo-50 p-4 dark:from-violet-950/50 dark:to-indigo-950/40"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white text-violet-600 shadow-sm dark:bg-slate-800"><Sparkles size={17}/></span><p className="mt-3 text-xs font-bold text-slate-800 dark:text-white">Every voice moves us forward</p><p className="mt-1 text-[11px] leading-5 text-slate-500 dark:text-slate-300">Thank you for making campus better.</p></div><button onClick={logout} className="mt-4 flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-500 transition hover:bg-red-50 hover:text-red-600"><LogOut size={17}/>Log out</button></aside>
    {open&&<button aria-label="Close menu" onClick={()=>setOpen(false)} className="fixed inset-0 z-30 bg-slate-950/25 lg:hidden"/>}
    <div className="min-h-screen lg:pl-[260px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-slate-200/70 bg-white/90 px-5 backdrop-blur-xl dark:border-slate-800 dark:bg-[#191925]/90 sm:px-8"><div className="flex items-center gap-3"><button onClick={()=>setOpen(true)} className="rounded-lg p-2 text-slate-600 lg:hidden"><Menu size={19}/></button><span className="text-sm font-semibold text-slate-700 dark:text-slate-200">{title}</span></div><div className="flex items-center gap-3"><ThemeButton/><div className="hidden h-8 w-px bg-slate-200 sm:block"/><div className="hidden text-right sm:block"><p className="text-xs font-bold text-slate-800 dark:text-white">{user?.name||'CampusVoice user'}</p><p className="text-[10px] capitalize text-slate-400">{isHost?'Campus host':'Student account'}</p></div><span className="grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-violet-500 to-indigo-500 text-xs font-bold text-white">{(user?.name||'U').split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase()}</span></div></header><main className="mx-auto max-w-[1380px] px-5 py-7 sm:px-8 sm:py-9"><Outlet/></main></div>
  </div>;
}
function PageTitle({ eyebrow, title, description, action }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-violet-600">{eyebrow}</p><h1 className="font-display mt-2 text-2xl font-extrabold tracking-tight text-slate-900 dark:text-white sm:text-[30px]">{title}</h1>{description&&<p className="mt-1.5 text-sm text-slate-500 dark:text-slate-400">{description}</p>}</div>{action}</div> }
function Panel({ children, className='' }) { return <section className={`surface rounded-2xl p-5 shadow-[0_2px_12px_-9px_rgba(30,25,60,.18)] sm:p-6 ${className}`}>{children}</section> }
function Empty({ title, children }) { return <div className="py-12 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-violet-50 text-violet-600"><MessageSquare size={22}/></span><p className="mt-3 text-sm font-bold text-slate-800 dark:text-white">{title}</p><p className="mt-1 text-xs text-slate-500">{children}</p></div> }
function useResource(path, refreshKey=0) {
  const [data,setData]=useState(null);const [error,setError]=useState('');
  useEffect(()=>{let active=true;setError('');api(path).then(x=>{if(active)setData(x)}).catch(e=>{if(active)setError(e.message)});return()=>{active=false}},[path,refreshKey]);
  return {data,error};
}
function StudentDashboard() {
  const user=useAuthUser();const {data,error}=useResource('/student/summary');
  return <><PageTitle eyebrow="Student workspace" title={`Good to see you, ${(user?.name||'there').split(' ')[0]}.`} description="Your perspective makes a difference. What would you like to do today?"/>{error&&<ErrorBox>{error}</ErrorBox>}
    <div className="grid gap-4 sm:grid-cols-3"><StatCard icon={MessageSquare} label="Feedback shared" value={data?.feedbackCount??'—'} color="violet"/><StatCard icon={CircleHelp} label="Open complaints" value={data?.openComplaints??'—'} color="amber"/><StatCard icon={CheckCircle2} label="Resolved concerns" value={data?.resolvedComplaints??'—'} color="emerald"/></div>
    <div className="mt-7 flex items-end justify-between"><div><h2 className="font-display text-lg font-bold text-slate-900 dark:text-white">Find your feedback space</h2><p className="mt-1 text-sm text-slate-500">Choose an area of campus and share what you think.</p></div><Link to="/student/feedback" className="hidden text-sm font-semibold text-violet-700 sm:inline-flex">View all <ArrowRight size={15} className="ml-1"/></Link></div>
    <div className="mt-4 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{categories.map(({name,description,icon:Icon,color})=><Link key={name} to={`/student/feedback?category=${encodeURIComponent(name)}`} className="surface group rounded-2xl p-5 transition hover:-translate-y-1 hover:shadow-lg hover:shadow-violet-100/60"><div className="flex items-start justify-between"><span className={`grid h-11 w-11 place-items-center rounded-xl ${color}`}><Icon size={21}/></span><ArrowUpRight size={18} className="text-slate-300 transition group-hover:text-violet-600"/></div><h3 className="mt-4 text-sm font-bold text-slate-900 dark:text-white">{name}</h3><p className="mt-1 text-xs text-slate-500">{description}</p><span className="mt-4 inline-flex text-xs font-semibold text-violet-700">Share feedback <ArrowRight size={13} className="ml-1"/></span></Link>)}</div>
    <div className="mt-7 grid gap-5 lg:grid-cols-2"><RecentFeedback/><RecentComplaints student/></div>
  </>;
}
function StatCard({icon:Icon,label,value,color='violet',detail}){const styles={violet:'bg-violet-50 text-violet-700',amber:'bg-amber-50 text-amber-700',emerald:'bg-emerald-50 text-emerald-700',blue:'bg-blue-50 text-blue-700'};return <Panel><div className="flex items-center justify-between"><span className={`grid h-10 w-10 place-items-center rounded-xl ${styles[color]}`}><Icon size={19}/></span><ArrowUpRight size={16} className="text-slate-300"/></div><p className="font-display mt-4 text-3xl font-extrabold text-slate-900 dark:text-white">{value}</p><p className="mt-1 text-xs font-medium text-slate-500">{label}</p>{detail&&<p className="mt-2 text-[11px] text-emerald-600">{detail}</p>}</Panel>}
function ErrorBox({children}){return <div role="alert" className="mb-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{children}</div>}
function FeedbackForm() {
  const location=useLocation();const initial=new URLSearchParams(location.search).get('category');const [category,setCategory]=useState(categories.some(x=>x.name===initial)?initial:'Faculty');const [rating,setRating]=useState(0);const [comment,setComment]=useState('');const [anonymous,setAnonymous]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);
  const {data:questionData}=useResource('/student/questions');
  const prompts=Array.isArray(questionData)?questionData.filter(question=>question.category===category):[];
  async function send(e){e.preventDefault();setBusy(true);setError('');setMessage('');try{await api('/student/feedback',{method:'POST',body:JSON.stringify({category,rating,comment,anonymous})});setMessage('Thank you! Your feedback has been shared with your campus team.');setRating(0);setComment('')}catch(err){setError(err.message)}finally{setBusy(false)}}
  return <><PageTitle eyebrow="Student workspace" title="Give feedback" description="A few honest words can make a meaningful difference."/><div className="grid gap-6 lg:grid-cols-[1fr_320px]"><Panel className="max-w-3xl">{error&&<ErrorBox>{error}</ErrorBox>}{message&&<div className="mb-5 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{message}</div>}<form onSubmit={send} className="space-y-6"><label className="block text-sm font-semibold text-slate-800 dark:text-white">What would you like to share about?<select className="field mt-2" value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c.name}>{c.name}</option>)}</select></label>{prompts.length>0&&<div className="rounded-xl bg-violet-50/70 p-4 dark:bg-violet-950/30"><p className="text-xs font-bold text-violet-800 dark:text-violet-200">A few things to consider</p><ul className="mt-2 space-y-1.5">{prompts.map(question=><li key={question._id} className="text-xs leading-5 text-slate-600 dark:text-slate-300">• {question.text}</li>)}</ul></div>}<div><p className="text-sm font-semibold text-slate-800 dark:text-white">How was your experience?</p><div className="mt-3 flex gap-2">{[1,2,3,4,5].map(x=><button type="button" aria-label={`${x} stars`} onClick={()=>setRating(x)} key={x} className={`grid h-11 w-11 place-items-center rounded-xl border text-lg transition ${rating>=x?'border-violet-300 bg-violet-50 text-violet-600':'border-slate-200 text-slate-300 hover:border-violet-200'}`}>★</button>)}</div>{rating>0&&<p className="mt-2 text-xs text-slate-500">{['','Needs improvement','Could be better','It was okay','Really good','Excellent'][rating]}</p>}</div><label className="block text-sm font-semibold text-slate-800 dark:text-white">Your thoughts<textarea required minLength={5} maxLength={3000} rows={5} className="field mt-2 resize-y" value={comment} onChange={e=>setComment(e.target.value)} placeholder="What went well? What could we do better?"/></label><label className="flex cursor-pointer items-start gap-3"><input type="checkbox" checked={anonymous} onChange={e=>setAnonymous(e.target.checked)} className="mt-1 accent-violet-600"/><span><span className="text-sm font-semibold text-slate-800 dark:text-white">Share anonymously</span><span className="mt-0.5 block text-xs text-slate-500">Your name will not be shown alongside this feedback.</span></span></label><button disabled={busy||!rating} className="inline-flex items-center rounded-xl bg-violet-600 px-5 py-3 text-sm font-bold text-white transition hover:bg-violet-700 disabled:cursor-not-allowed disabled:opacity-50">{busy?'Sending…':'Send feedback'}<Send size={15} className="ml-2"/></button></form></Panel><Panel className="h-fit"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-50 text-violet-700"><Shield size={19}/></span><h3 className="mt-4 text-sm font-bold text-slate-900 dark:text-white">Your voice, your choice.</h3><p className="mt-2 text-xs leading-5 text-slate-500">Feedback is shared with authorized campus hosts to help improve your student experience. Choose anonymous sharing any time.</p><div className="mt-5 border-t border-slate-100 pt-4 text-xs leading-5 text-slate-500"><Check size={14} className="mr-1 inline text-emerald-600"/>Honest, respectful feedback helps everyone.</div></Panel></div></>;
}
function HistoryPage({host=false}) {
  const path=host?'/host/feedback':'/student/feedback';const {data,error}=useResource(path);const items=Array.isArray(data)?data:[];
  return <><PageTitle eyebrow={host?'Campus overview':'Student workspace'} title={host?'Student feedback':'My feedback history'} description={host?'Recent feedback from across your campus.':'A record of the ideas you’ve shared.'} action={host?<Link to="/host/reports" className="rounded-xl border border-slate-200 px-4 py-2.5 text-xs font-semibold text-slate-700 hover:bg-white">View analytics <BarChart3 size={15} className="ml-2 inline"/></Link>:null}/>{error&&<ErrorBox>{error}</ErrorBox>}<Panel><div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="border-b border-slate-100 text-[11px] uppercase tracking-wider text-slate-400"><th className="pb-3 font-semibold">Category</th>{host&&<th className="pb-3 font-semibold">Student</th>}<th className="pb-3 font-semibold">Feedback</th><th className="pb-3 font-semibold">Rating</th><th className="pb-3 font-semibold">Date</th></tr></thead><tbody>{items.map(x=><tr key={x._id} className="border-b border-slate-50 last:border-0"><td className="py-4 font-semibold text-slate-800 dark:text-slate-200">{x.category}</td>{host&&<td className="py-4 text-xs text-slate-500">{x.anonymous?'Anonymous':x.student?.name||'Student'}</td>}<td className="max-w-sm py-4 text-xs leading-5 text-slate-600 dark:text-slate-300">{x.comment}</td><td className="py-4 text-amber-500">{'★'.repeat(x.rating)}<span className="text-slate-200">{'★'.repeat(5-x.rating)}</span></td><td className="py-4 text-xs text-slate-500">{new Date(x.createdAt).toLocaleDateString()}</td></tr>)}</tbody></table>{!items.length&&!error&&<Empty title="No feedback yet">New feedback will show up here.</Empty>}</div></Panel></>;
}
function RecentFeedback(){const {data,error}=useResource('/student/feedback?limit=4');const items=Array.isArray(data)?data:[];return <Panel><div className="flex items-center justify-between"><div><h3 className="text-sm font-bold text-slate-900 dark:text-white">Your recent feedback</h3><p className="mt-1 text-xs text-slate-500">A little progress adds up.</p></div><Link to="/student/history" className="text-xs font-semibold text-violet-700">View all</Link></div>{error?<p className="mt-4 text-xs text-red-600">{error}</p>:items.length?<div className="mt-4 divide-y divide-slate-100">{items.map(x=><div key={x._id} className="flex items-center justify-between py-3"><div><p className="text-xs font-semibold text-slate-800 dark:text-slate-200">{x.category}</p><p className="mt-1 max-w-[280px] truncate text-[11px] text-slate-500">{x.comment}</p></div><span className="text-xs text-amber-500">{'★'.repeat(x.rating)}</span></div>)}</div>:<Empty title="Your story starts here">Feedback you share will appear here.</Empty>}</Panel>}
function Complaints({host=false}) {
  const [refresh,setRefresh]=useState(0);const [form,setForm]=useState({subject:'',category:'Campus infrastructure',description:''});const [error,setError]=useState('');const [success,setSuccess]=useState('');
  const {data, error:loadError}=useResource(host?'/host/complaints':'/student/complaints',refresh);const items=Array.isArray(data)?data:[];
  async function submit(e){e.preventDefault();setError('');setSuccess('');try{await api('/student/complaints',{method:'POST',body:JSON.stringify(form)});setSuccess('Your concern has been submitted.');setForm({subject:'',category:'Campus infrastructure',description:''});setRefresh(x=>x+1)}catch(err){setError(err.message)}}
  async function resolve(id,status){setError('');try{await api(`/host/complaints/${id}`,{method:'PATCH',body:JSON.stringify({status})});setRefresh(x=>x+1)}catch(err){setError(err.message)}}
  return <><PageTitle eyebrow={host?'Campus overview':'Student workspace'} title={host?'Student complaints':'My complaints'} description={host?'Review and follow up on student concerns.':'Raise a concern and keep track of the response.'}/>{(error||loadError)&&<ErrorBox>{error||loadError}</ErrorBox>}{success&&<div className="mb-5 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{success}</div>}<div className={host?'':'grid gap-6 lg:grid-cols-[.8fr_1.2fr]'}>{!host&&<Panel className="h-fit"><h3 className="text-sm font-bold text-slate-900 dark:text-white">Tell us what’s on your mind</h3><p className="mt-1 text-xs text-slate-500">Your concern will go to the campus team.</p><form onSubmit={submit} className="mt-5 space-y-4"><label className="block text-xs font-semibold">Subject<input required maxLength={150} className="field mt-2 text-sm" value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})} placeholder="A short summary"/></label><label className="block text-xs font-semibold">Campus area<select className="field mt-2 text-sm" value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{categories.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label className="block text-xs font-semibold">Details<textarea required minLength={10} maxLength={3000} rows={4} className="field mt-2 resize-y text-sm" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Share any details that will help us understand"/></label><button className="rounded-xl bg-violet-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-violet-700">Submit concern <Send size={13} className="ml-1 inline"/></button></form></Panel>}<Panel><h3 className="mb-3 text-sm font-bold text-slate-900 dark:text-white">{host?'All concerns':'Your submitted concerns'}</h3>{items.length?<div className="divide-y divide-slate-100">{items.map(x=><div key={x._id} className="py-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-semibold text-slate-800 dark:text-slate-200">{x.subject}</p><p className="mt-1 text-[11px] text-slate-500">{x.category} · {host?`${x.student?.name||'Student'} · `:''}{new Date(x.createdAt).toLocaleDateString()}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold capitalize ${x.status==='resolved'?'bg-emerald-50 text-emerald-700':x.status==='in progress'?'bg-blue-50 text-blue-700':'bg-amber-50 text-amber-700'}`}>{x.status}</span></div><p className="mt-3 text-xs leading-5 text-slate-600 dark:text-slate-300">{x.description}</p>{host&&x.status!=='resolved'&&<button onClick={()=>resolve(x._id,x.status==='open'?'in progress':'resolved')} className="mt-3 text-xs font-semibold text-violet-700">{x.status==='open'?'Mark in progress':'Resolve concern'} <ArrowRight size={12} className="ml-1 inline"/></button>}</div>)}</div>:!loadError&&<Empty title="No concerns to show">Submitted concerns will appear here.</Empty>}</Panel></div></>;
}
function RecentComplaints({student=false}){const {data,error}=useResource(student?'/student/complaints?limit=3':'/host/complaints?limit=3');const rows=Array.isArray(data)?data:[];return <Panel><div className="flex items-center justify-between"><div><h3 className="text-sm font-bold text-slate-900 dark:text-white">{student?'Your concerns':'Recent concerns'}</h3><p className="mt-1 text-xs text-slate-500">{student?'Stay in the loop.':'A pulse on open concerns.'}</p></div><Link to={student?'/student/complaints':'/host/complaints'} className="text-xs font-semibold text-violet-700">View all</Link></div>{error?<p className="mt-4 text-xs text-red-600">{error}</p>:rows.length?<div className="mt-4 space-y-3">{rows.map(x=><div key={x._id} className="flex items-start justify-between gap-3 rounded-xl bg-slate-50 p-3 dark:bg-slate-800"><div><p className="text-xs font-semibold text-slate-800 dark:text-slate-200">{x.subject}</p><p className="mt-1 text-[10px] text-slate-500">{x.category} · {new Date(x.createdAt).toLocaleDateString()}</p></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[9px] font-bold capitalize text-amber-700">{x.status}</span></div>)}</div>:<Empty title="All clear">Concerns and updates will show up here.</Empty>}</Panel>}
function Profile() {
  const user=useAuthUser();const [name,setName]=useState(user?.name||'');const [success,setSuccess]=useState('');const [error,setError]=useState('');
  async function save(e){e.preventDefault();setError('');setSuccess('');try{const {user:updated}=await api('/student/profile',{method:'PATCH',body:JSON.stringify({name})});localStorage.setItem('campusvoice_user',JSON.stringify(updated));setSuccess('Your profile has been updated.')}catch(err){setError(err.message)}}
  return <><PageTitle eyebrow="Student workspace" title="My profile" description="Keep your account details up to date."/><Panel className="max-w-2xl">{error&&<ErrorBox>{error}</ErrorBox>}{success&&<div className="mb-5 rounded-xl bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{success}</div>}<div className="mb-6 flex items-center gap-4"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-violet-100 text-lg font-bold text-violet-700">{(user?.name||'U').slice(0,1).toUpperCase()}</span><div><p className="font-semibold text-slate-900 dark:text-white">{user?.name}</p><p className="text-xs capitalize text-slate-500">{user?.role} account</p></div></div><form onSubmit={save} className="space-y-4"><label className="block text-sm font-semibold">Full name<input required maxLength={100} className="field mt-2" value={name} onChange={e=>setName(e.target.value)}/></label><label className="block text-sm font-semibold">Email address<input disabled className="field mt-2 opacity-70" value={user?.email||''}/></label><button className="rounded-xl bg-violet-600 px-5 py-3 text-sm font-bold text-white hover:bg-violet-700">Save changes</button></form></Panel></>;
}
function HostDashboard() {
  const {data,error}=useResource('/host/summary');
  return <><PageTitle eyebrow="Campus host workspace" title="Campus overview" description="Listen to what students are saying and see where to focus next." action={<Link to="/host/reports" className="rounded-xl bg-violet-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-violet-700"><Download size={14} className="mr-2 inline"/>Reports</Link>}/>{error&&<ErrorBox>{error}</ErrorBox>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={MessageSquare} label="Feedback responses" value={data?.feedbackCount??'—'} color="violet"/><StatCard icon={Users} label="Registered students" value={data?.studentCount??'—'} color="blue"/><StatCard icon={CircleHelp} label="Open complaints" value={data?.openComplaints??'—'} color="amber"/><StatCard icon={Activity} label="Average rating" value={data?.averageRating?`${data.averageRating.toFixed(1)} / 5`:'—'} color="emerald"/></div>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><Panel><div className="flex items-start justify-between"><div><h3 className="text-sm font-bold text-slate-900 dark:text-white">Student voice over time</h3><p className="mt-1 text-xs text-slate-500">Responses across the last six months</p></div><span className="rounded-lg bg-violet-50 p-2 text-violet-600"><BarChart3 size={17}/></span></div><div className="mt-6 h-[245px]">{data?.trend?.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={data.trend}><defs><linearGradient id="colorResponses" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b5cf6" stopOpacity={.22}/><stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#f0eef5" vertical={false}/><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#9492a5'}}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#9492a5'}}/><Tooltip/><Area type="monotone" dataKey="responses" stroke="#8055e9" strokeWidth={2.5} fill="url(#colorResponses)"/></AreaChart></ResponsiveContainer>:<div className="grid h-full place-items-center text-xs text-slate-400">No feedback responses yet.</div>}</div></Panel><Panel><h3 className="text-sm font-bold text-slate-900 dark:text-white">Feedback by category</h3><p className="mt-1 text-xs text-slate-500">Where students are sharing most</p><div className="mt-4 h-[245px]"><ResponsiveContainer width="100%" height="100%"><BarChart layout="vertical" data={data?.categories?.length?data.categories:categories.map(c=>({name:c.name,count:0}))} margin={{left:8,right:8}}><CartesianGrid stroke="#f0eef5" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="name" width={130} tickLine={false} axisLine={false} tick={{fontSize:10,fill:'#737188'}}/><Tooltip/><Bar dataKey="count" fill="#8b5cf6" radius={[0,5,5,0]} barSize={13}/></BarChart></ResponsiveContainer></div></Panel></div>
    <div className="mt-6 grid gap-5 xl:grid-cols-2"><HistoryPreview/><RecentComplaints/></div>
  </>;
}
function HistoryPreview(){const {data,error}=useResource('/host/feedback?limit=4');const items=Array.isArray(data)?data:[];return <Panel><div className="flex items-center justify-between"><div><h3 className="text-sm font-bold text-slate-900 dark:text-white">Latest student feedback</h3><p className="mt-1 text-xs text-slate-500">Fresh perspectives from your community.</p></div><Link to="/host/feedback" className="text-xs font-semibold text-violet-700">See all</Link></div>{error?<p className="mt-4 text-xs text-red-600">{error}</p>:items.length?<div className="mt-4 space-y-3">{items.map(x=><div key={x._id} className="rounded-xl bg-slate-50 p-3 dark:bg-slate-800"><div className="flex justify-between gap-2"><p className="text-xs font-bold text-slate-800 dark:text-slate-200">{x.category} <span className="font-normal text-slate-400">· {x.anonymous?'Anonymous':x.student?.name||'Student'}</span></p><span className="whitespace-nowrap text-[11px] text-amber-500">{'★'.repeat(x.rating)}</span></div><p className="mt-1.5 text-xs leading-5 text-slate-600 dark:text-slate-300">{x.comment}</p></div>)}</div>:<Empty title="No feedback yet">Student submissions will show here.</Empty>}</Panel>}
function StudentsPage(){
  const {data,error}=useResource('/host/students');const students=Array.isArray(data)?data:[];
  return <><PageTitle eyebrow="Campus host workspace" title="Manage students" description="View registered student accounts."/><Panel>{error&&<ErrorBox>{error}</ErrorBox>}<div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="border-b border-slate-100 text-[11px] uppercase tracking-wider text-slate-400"><th className="pb-3">Student</th><th className="pb-3">Student ID</th><th className="pb-3">Email</th><th className="pb-3">Joined</th></tr></thead><tbody>{students.map(x=><tr key={x._id} className="border-b border-slate-50 last:border-0"><td className="py-4 font-semibold text-slate-800 dark:text-slate-200">{x.name}</td><td className="py-4 text-xs text-slate-500">{x.studentId}</td><td className="py-4 text-xs text-slate-500">{x.email}</td><td className="py-4 text-xs text-slate-500">{new Date(x.createdAt).toLocaleDateString()}</td></tr>)}</tbody></table>{students.length===0&&!error&&<Empty title="No students registered">Student accounts will appear here.</Empty>}</div></Panel></>;
}
function Reports(){
 const {data,error}=useResource('/host/summary');const rows=data?.categories||[];
 function csv(){if(!rows.length)return;const escape=value=>`"${String(value).replaceAll('"','""')}"`;const contents=[['Category','Responses','Average rating'],...rows.map(x=>[x.name,x.count,x.averageRating??''])].map(row=>row.map(escape).join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([contents],{type:'text/csv;charset=utf-8'}));link.download='campusvoice-report.csv';link.click();URL.revokeObjectURL(link.href)}
 return <><PageTitle eyebrow="Campus host workspace" title="Reports & analytics" description="Explore feedback trends and export a category summary." action={<button onClick={csv} disabled={!rows.length} className="rounded-xl bg-violet-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-violet-700 disabled:opacity-50"><Download size={14} className="mr-2 inline"/>Export CSV</button>}/>{error&&<ErrorBox>{error}</ErrorBox>}<div className="grid gap-4 sm:grid-cols-3"><StatCard icon={MessageSquare} label="Total feedback" value={data?.feedbackCount??'—'} color="violet"/><StatCard icon={Users} label="Student community" value={data?.studentCount??'—'} color="blue"/><StatCard icon={Activity} label="Average rating" value={data?.averageRating?`${data.averageRating.toFixed(1)} / 5`:'—'} color="emerald"/></div><Panel className="mt-6"><h3 className="text-sm font-bold text-slate-900 dark:text-white">Category performance</h3><p className="mt-1 text-xs text-slate-500">Feedback volume and student sentiment for each area.</p><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[500px] text-left text-sm"><thead><tr className="border-b border-slate-100 text-[11px] uppercase tracking-wider text-slate-400"><th className="pb-3">Category</th><th className="pb-3">Responses</th><th className="pb-3">Average rating</th></tr></thead><tbody>{rows.map(x=><tr key={x.name} className="border-b border-slate-50 last:border-0"><td className="py-4 font-semibold">{x.name}</td><td className="py-4">{x.count}</td><td className="py-4 text-amber-500">{x.averageRating?`${x.averageRating.toFixed(1)} ★`:'—'}</td></tr>)}</tbody></table></div></Panel></>;
}
function ManageSettings(){
 const [tab,setTab]=useState('questions');const [data,setData]=useState([]);const [value,setValue]=useState('');const [category,setCategory]=useState('Faculty');const [start,setStart]=useState('');const [end,setEnd]=useState('');const [error,setError]=useState('');const [success,setSuccess]=useState('');
 useEffect(()=>{let active=true;api(`/host/${tab}`).then(x=>{if(active)setData(x)}).catch(e=>{if(active)setError(e.message)});return()=>{active=false}},[tab]);
 async function add(e){e.preventDefault();setError('');setSuccess('');try{await api(`/host/${tab}`,{method:'POST',body:JSON.stringify(tab==='questions'?{text:value,category}:{name:value,startDate:start,endDate:end})});setSuccess(tab==='questions'?'Question added.':'Feedback period created.');setValue('');const x=await api(`/host/${tab}`);setData(x)}catch(err){setError(err.message)}}
 async function remove(id){setError('');try{await api(`/host/${tab}/${id}`,{method:'DELETE'});setData(await api(`/host/${tab}`))}catch(err){setError(err.message)}}
 return <><PageTitle eyebrow="Campus host workspace" title="Questions & periods" description="Keep feedback prompts and collection periods relevant."/><div className="mb-5 inline-flex rounded-xl bg-slate-100 p-1 dark:bg-slate-800"><button onClick={()=>setTab('questions')} className={`rounded-lg px-4 py-2 text-xs font-semibold ${tab==='questions'?'bg-white text-violet-700 shadow-sm dark:bg-slate-700':'text-slate-500'}`}>Feedback questions</button><button onClick={()=>setTab('periods')} className={`rounded-lg px-4 py-2 text-xs font-semibold ${tab==='periods'?'bg-white text-violet-700 shadow-sm dark:bg-slate-700':'text-slate-500'}`}>Feedback periods</button></div>{(error)&&<ErrorBox>{error}</ErrorBox>}{success&&<div className="mb-5 rounded-xl bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{success}</div>}<div className="grid gap-6 lg:grid-cols-[.9fr_1.1fr]"><Panel><h3 className="text-sm font-bold text-slate-900 dark:text-white">{tab==='questions'?'Add a feedback question':'Create a feedback period'}</h3><form onSubmit={add} className="mt-4 space-y-4"><label className="block text-xs font-semibold">{tab==='questions'?'Question':'Period name'}<input required maxLength={250} className="field mt-2 text-sm" value={value} onChange={e=>setValue(e.target.value)} placeholder={tab==='questions'?'e.g. What would improve your experience?':'e.g. Fall semester 2026'}/></label>{tab==='questions'?<label className="block text-xs font-semibold">Category<select className="field mt-2 text-sm" value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c.name}>{c.name}</option>)}</select></label>:<div className="grid grid-cols-2 gap-3"><label className="block text-xs font-semibold">Starts<input required type="date" className="field mt-2 text-xs" value={start} onChange={e=>setStart(e.target.value)}/></label><label className="block text-xs font-semibold">Ends<input required type="date" className="field mt-2 text-xs" value={end} onChange={e=>setEnd(e.target.value)}/></label></div>}<button className="rounded-xl bg-violet-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-violet-700">Add {tab==='questions'?'question':'period'}</button></form></Panel><Panel><h3 className="text-sm font-bold text-slate-900 dark:text-white">Current {tab}</h3>{data.length?<div className="mt-4 divide-y divide-slate-100">{data.map(x=><div key={x._id} className="flex items-start justify-between gap-3 py-3"><div><p className="text-xs font-semibold text-slate-800 dark:text-slate-200">{tab==='questions'?x.text:x.name}</p><p className="mt-1 text-[10px] text-slate-500">{tab==='questions'?x.category:`${new Date(x.startDate).toLocaleDateString()} – ${new Date(x.endDate).toLocaleDateString()}`}</p></div><button onClick={()=>remove(x._id)} className="rounded-lg px-2 py-1 text-xs font-semibold text-red-500 hover:bg-red-50">Remove</button></div>)}</div>:<Empty title={`No ${tab} yet`}>Create the first one with the form.</Empty>}</Panel></div></>;
}
function SystemSettings(){const [settings,setSettings]=useState(null);const [error,setError]=useState('');const [success,setSuccess]=useState('');useEffect(()=>{api('/host/settings').then(setSettings).catch(e=>setError(e.message))},[]);async function save(e){e.preventDefault();setError('');setSuccess('');try{const result=await api('/host/settings',{method:'PATCH',body:JSON.stringify(settings)});setSettings(result);setSuccess('Settings saved.')}catch(err){setError(err.message)}}return <><PageTitle eyebrow="Campus host workspace" title="System settings" description="Control how feedback is collected across your campus."/><Panel className="max-w-2xl">{error&&<ErrorBox>{error}</ErrorBox>}{success&&<div className="mb-5 rounded-xl bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{success}</div>}{settings&&<form onSubmit={save} className="space-y-5"><label className="flex items-start justify-between gap-4"><span><span className="block text-sm font-semibold text-slate-800 dark:text-white">Student registration</span><span className="mt-1 block text-xs text-slate-500">Allow students to create their own accounts.</span></span><input type="checkbox" className="mt-1 h-4 w-4 accent-violet-600" checked={settings.registrationEnabled} onChange={e=>setSettings({...settings,registrationEnabled:e.target.checked})}/></label><div className="border-t border-slate-100 pt-5"><p className="text-sm font-semibold text-slate-800 dark:text-white">Campus name</p><input className="field mt-2" maxLength={100} value={settings.campusName||''} onChange={e=>setSettings({...settings,campusName:e.target.value})}/></div><div className="border-t border-slate-100 pt-5"><p className="text-sm font-semibold text-slate-800 dark:text-white">Feedback anonymity</p><p className="mt-1 text-xs text-slate-500">Students may choose to submit anonymously; hosts will see those responses without identity details.</p></div><button className="rounded-xl bg-violet-600 px-5 py-3 text-sm font-bold text-white hover:bg-violet-700">Save settings</button></form>}</Panel></>}

export default function App(){
 useEffect(()=>{if(localStorage.getItem('campusvoice_theme')==='dark')document.documentElement.classList.add('dark')},[]);
 return <AnimatePresence mode="wait"><Routes>
   <Route path="/" element={<Home/>}/>
   <Route path="/login/:role" element={<Login/>}/>
   <Route element={<Guard role="student"/>}><Route path="/student" element={<AppLayout role="student"/>}><Route index element={<Navigate to="dashboard" replace/>}/><Route path="dashboard" element={<StudentDashboard/>}/><Route path="feedback" element={<FeedbackForm/>}/><Route path="history" element={<HistoryPage/>}/><Route path="complaints" element={<Complaints/>}/><Route path="profile" element={<Profile/>}/><Route path="*" element={<Navigate to="dashboard" replace/>}/></Route></Route>
   <Route element={<Guard role="host"/>}><Route path="/host" element={<AppLayout role="host"/>}><Route index element={<Navigate to="dashboard" replace/>}/><Route path="dashboard" element={<HostDashboard/>}/><Route path="feedback" element={<HistoryPage host/>}/><Route path="students" element={<StudentsPage/>}/><Route path="complaints" element={<Complaints host/>}/><Route path="reports" element={<Reports/>}/><Route path="manage" element={<ManageSettings/>}/><Route path="settings" element={<SystemSettings/>}/><Route path="*" element={<Navigate to="dashboard" replace/>}/></Route></Route>
   <Route path="*" element={<Navigate to="/" replace/>}/>
 </Routes></AnimatePresence>;
}
